# Complete NixOS Flakes + Home Manager Setup Guide

## Step 1: Enable Flakes
After fresh NixOS installation, enable flakes:
```bash
sudo mkdir -p /etc/nix
echo "experimental-features = nix-command flakes" | sudo tee -a /etc/nix/nix.conf
sudo systemctl restart nix-daemon
```

## Step 2: Create Configuration Directory
```bash
cd /etc/nixos
sudo git init
```

## Step 3: Create flake.nix
```nix
{
  description = "NixOS configuration with Home Manager";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    home-manager = {
      url = "github:nix-community/home-manager";
      inputs.nixpkgs.follows = "nixpkgs";
    };
  };

  outputs = { self, nixpkgs, home-manager, ... }: {
    nixosConfigurations.myhostname = nixpkgs.lib.nixosSystem {
      system = "x86_64-linux";
      modules = [
        ./configuration.nix
        home-manager.nixosModules.home-manager
        {
          home-manager.useGlobalPkgs = true;
          home-manager.useUserPackages = true;
          home-manager.users.myuser = import ./home.nix;
        }
      ];
    };
  };
}
```

## Step 4: Create configuration.nix
```nix
{ config, pkgs, ... }:

{
  imports = [ ./hardware-configuration.nix ];

  networking.hostName = "myhostname";
  time.timeZone = "America/New_York";

  # GNOME with Wayland
  services.xserver = {
    enable = true;
    displayManager.gdm = {
      enable = true;
      wayland = true;
    };
    desktopManager.gnome.enable = true;
  };

  # User
  users.users.myuser = {
    isNormalUser = true;
    extraGroups = [ "wheel" "networkmanager" ];
  };

  # System packages
  environment.systemPackages = with pkgs; [
    # Standard tools
    curl wget git htop vim tree
    unzip zip tmux ripgrep fd

    # Applications
    brave bitwarden
  ];

  nixpkgs.config.allowUnfree = true;
  system.stateVersion = "23.11";
}
```

## Step 5: Create home.nix
```nix
{ config, pkgs, ... }:

{
  home.username = "myuser";
  home.homeDirectory = "/home/myuser";
  home.stateVersion = "23.11";

  programs.neovim = {
    enable = true;
    viAlias = true;
    vimAlias = true;
  };

  programs.vscode = {
    enable = true;
    package = pkgs.vscode;
  };

  home.packages = with pkgs; [
    zed-editor
  ];

  programs.home-manager.enable = true;
}
```

## Step 6: Apply Configuration
```bash
sudo nixos-rebuild switch --flake /etc/nixos#myhostname
```

