```cpp
#include <QCoreApplication>
#include <QDebug>
#include <QSet>
#include "xlsxdocument.h"

bool parseToInt(const QVariant &cellValue, int &result) {
    // Handle numeric types
    if (cellValue.type() == QVariant::Double || cellValue.type() == QVariant::Int) {
        double d = cellValue.toDouble();
        int i = static_cast<int>(d);
        if (qFuzzyCompare(d + 1.0, i + 1.0)) {
            result = i;
            return true;
        }
        return false;
    }

    // Handle string types
    QString str = cellValue.toString().trimmed();
    if (str.isEmpty()) return false;

    bool ok;
    // Hex: 0x2A
    if (str.startsWith("0x", Qt::CaseInsensitive)) {
        result = str.mid(2).toInt(&ok, 16);
        return ok;
    }
    // Binary: 0b101010
    if (str.startsWith("0b", Qt::CaseInsensitive)) {
        result = str.mid(2).toInt(&ok, 2);
        return ok;
    }
    // Octal: 052
    if (str.startsWith("0") && str.length() > 1) {
        result = str.toInt(&ok, 8);
        return ok;
    }
    // Decimal
    result = str.toInt(&ok, 10);
    return ok;
}

int main(int argc, char *argv[]) {
    QCoreApplication a(argc, argv);

    QXlsx::Document xlsx("file.xlsx");
    if (!xlsx.load()) {
        qWarning() << "Failed to load file";
        return -1;
    }

    QVariant cellValue = xlsx.read("A1");
    if (!cellValue.isValid()) {
        qWarning() << "Invalid cell";
        return -1;
    }

    int number;
    if (!parseToInt(cellValue, number)) {
        qDebug() << "Cannot parse cell value";
        return -1;
    }

    QSet<int> allowed = {0, 1, 2, 3, 10, 11, 42};
    if (allowed.contains(number)) {
        qDebug() << "Valid number:" << number;
    } else {
        qDebug() << "Invalid number:" << number;
    }

    return 0;
}
```

