    int cnt;

    Node() : cnt(0) {
        children.fill(nullptr);
    }
};

class Trie {
public:
    Trie() : root(new Node()) {}

    void insert(const string& s) {
        Node* curr = root;
        for (char c : s) {
            int idx = c - 'a';
            if (!curr->children[idx]) {
                curr->children[idx] = new Node();
            }
            curr = curr->children[idx];
            curr->cnt++;
        }
