        Node* curr = root;
        int sum = 0;
        for (char c : s) {
            int idx = c - 'a';
            if (!curr->children[idx]) break;
            curr = curr->children[idx];
            sum += curr->cnt;
        }
        return sum;
    }

private:
    Node* root;
};
```

