#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int a) {
        return parent[a] == a ? a : parent[a] = find(parent[a]);
    }
    void unite(int a, int b) {
        parent[find(a)] = find(b);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    DSU dsu(n);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u-1, v-1);
    }

    // Find cheapest house in each component
    map<int, int> comp_min;
    for (int i = 0; i < n; i++) {
        int root = dsu.find(i);
        if (comp_min.find(root) == comp_min.end() || a[i] < a[comp_min[root]]) {
            comp_min[root] = i;
        }
    }

    // Find global minimum
    int global_min = 0;
    for (int i = 1; i < n; i++) {
        if (a[i] < a[global_min]) global_min = i;
    }

    // Connect all components to global minimum
    vector<pair<int,int>> edges;
    int global_root = dsu.find(global_min);
    for (auto [root, node] : comp_min) {
        if (root != global_root) {
            edges.push_back({global_min + 1, node + 1});
        }
    }

    cout << edges.size() << "\n";
    for (auto [u, v] : edges) {
        cout << u << " " << v << "\n";
    }

