To create a geometry shader in Unity that samples a texture with transparency and creates extruded quads for non-transparent pixels, you need:

1. A shader with geometry shader support (Shader Model 4.0+)
2. Input mesh with points (one per pixel to sample)
3. Geometry shader that:
   - Samples texture at UV coordinates
   - Checks alpha threshold
   - Emits quad geometry for non-transparent pixels
   - Extrudes the quad

Here's a complete implementation:

```hlsl
Shader "Custom/ExtrudedPixelQuads"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _Extrude ("Extrude Factor", Float) = 0.1
        _AlphaThreshold ("Alpha Threshold", Range(0,1)) = 0.5
        _QuadSize ("Quad Size", Float) = 0.1
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }

        Pass
        {
            CGPROGRAM
            #pragma target 4.0
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag

            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _Extrude;
            float _AlphaThreshold;
            float _QuadSize;

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2g
            {
                float4 pos : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct g2f
            {
                float4 pos : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            v2g vert(appdata v)
            {
                v2g o;
                o.pos = v.vertex;
                o.uv = v.uv;
                return o;
            }

            [maxvertexcount(6)]
            void geom(point v2g input[1], inout TriangleStream<g2f> triStream)
            {
                float4 col = tex2Dlod(_MainTex, float4(input[0].uv, 0, 0));

                if (col.a < _AlphaThreshold)
                    return;

                float3 center = input[0].pos.xyz;
                float3 normal = float3(0, 0, 1);
                float3 right = float3(1, 0, 0) * _QuadSize;
                float3 up = float3(0, 1, 0) * _QuadSize;
                float3 extrude = normal * _Extrude;

                // Create quad vertices
                float3 v0 = center - right - up;
                float3 v1 = center + right - up;
                float3 v2 = center + right + up;
                float3 v3 = center - right + up;

                // Extrude vertices
                v0 += extrude;
                v1 += extrude;
                v2 += extrude;
                v3 += extrude;

                g2f o;

                // First triangle
                o.pos = UnityObjectToClipPos(float4(v0, 1));
                o.uv = input[0].uv;
                triStream.Append(o);

                o.pos = UnityObjectToClipPos(float4(v1, 1));
                triStream.Append(o);

                o.pos = UnityObjectToClipPos(float4(v2, 1));
                triStream.Append(o);

                // Second triangle
                o.pos = UnityObjectToClipPos(float4(v2, 1));
                triStream.Append(o);

                o.pos = UnityObjectToClipPos(float4(v3, 1));
                triStream.Append(o);

                o.pos = UnityObjectToClipPos(float4(v0, 1));
                triStream.Append(o);
            }

            fixed4 frag(g2f i) : SV_Target
            {
                return tex2D(_MainTex, i.uv);
            }
            ENDCG
        }
    }
}
```

