A perfect TypeScript function to wrap a function in a try/catch block and return a Result would include:

1. A Result type that represents success or failure
2. A wrapper function that handles both sync and async functions
3. Proper type safety and generics
4. Support for function arguments

Here's my implementation:

```typescript
// Result type definition
type Result<T, E = Error> = 
  | { success: true; data: T }
  | { success: false; error: E };

// Synchronous wrapper
function tryCatch<T, Args extends any[]>(
  fn: (...args: Args) => T
): (...args: Args) => Result<T> {
  return (...args: Args): Result<T> => {
    try {
      const data = fn(...args);
      return { success: true, data };
    } catch (error) {
      return { success: false, error: error as Error };
    }
  };
}

// Async wrapper
function tryCatchAsync<T, Args extends any[]>(
  fn: (...args: Args) => Promise<T>
): (...args: Args) => Promise<Result<T>> {
  return async (...args: Args): Promise<Result<T>> => {
    try {
      const data = await fn(...args);
      return { success: true, data };
    } catch (error) {
      return { success: false, error: error as Error };
    }
  };
}
```

