A perfect TypeScript function to wrap a function in a try/catch block and return a Result would include:

1. A Result type that represents success or failure
2. A wrapper function that can handle functions with any arguments
3. Support for both sync and async functions
4. Proper type inference

Here's my implementation:

```typescript
type Result<T, E = Error> = 
  | { success: true; value: T }
  | { success: false; error: E };

// Synchronous wrapper
function tryCatch<T, Args extends any[]>(
  fn: (...args: Args) => T
): (...args: Args) => Result<T> {
  return (...args: Args) => {
    try {
      const value = fn(...args);
      return { success: true, value };
    } catch (error) {
      return { success: false, error: error as Error };
    }
  };
}

// Async wrapper
function tryCatchAsync<T, Args extends any[]>(
  fn: (...args: Args) => Promise<T>
): (...args: Args) => Promise<Result<T>> {
  return async (...args: Args) => {
    try {
      const value = await fn(...args);
      return { success: true, value };
    } catch (error) {
      return { success: false, error: error as Error };
    }
  };
}
```

