```typescript
// interfaces/user.interface.ts
export interface CreateUserPayload {
  username: string;
  email: string;
  // other fields
}

export interface PermissionPayload {
  permissions: string[];
  // other fields
}

export interface UserCredentials {
  username: string;
  password: string;
}

// services/user-api.service.ts
import { APIRequestContext } from '@playwright/test';

export class UserApiService {
  constructor(private readonly request: APIRequestContext) {}

  async createUser(payload: CreateUserPayload): Promise<string> {
    const response = await this.request.post('/users/v2/create', { data: payload });
    if (response.status() !== 201) {
      throw new Error(`Failed to create user: ${response.status()}`);
    }
    const json = await response.json();
    return json.id;
  }

  async updatePermissions(userId: string, payload: PermissionPayload): Promise<UserCredentials> {
    const updatedPayload = { ...payload, id: userId };
    const response = await this.request.post('/users/v2/permissions', { data: updatedPayload });
    if (response.status() !== 200) {
      throw new Error(`Failed to update permissions: ${response.status()}`);
    }
    return await response.json();
  }
}

// factories/user.factory.ts
export class UserFactory {
  constructor(private readonly userApiService: UserApiService) {}

  async createAdminUser(
    createPayload: CreateUserPayload,
    permissionPayload: PermissionPayload
  ): Promise<UserCredentials> {
    const userId = await this.userApiService.createUser(createPayload);
    return await this.userApiService.updatePermissions(userId, permissionPayload);
  }
}

// pages/login.page.ts
