Looking at this problem, I need to find the k-th permutation of numbers [1,2,...,n] in lexicographic order.

**My Approach:**
1. Use factorial numbers to determine which digit should be at each position
2. For n numbers, there are (n-1)! permutations starting with each first digit
3. Calculate阶乘 values in advance
4. Convert k to 0-based index (k-1)
5. For each position, determine which remaining number to use by dividing k by the factorial of remaining positions
6. Remove used numbers and update k

**My Solution:**
```cpp
class Solution {
public:
    string getPermutation(int n, int k) {
        // Calculate factorials
        vector<int> factorial(n);
        factorial[0] = 1;
        for (int i = 1; i < n; i++) {
            factorial[i] = factorial[i-1] * i;
        }

        // Available numbers
        vector<int> numbers;
        for (int i = 1; i <= n; i++) {
            numbers.push_back(i);
        }

        k--; // Convert to 0-based
        string result;

        for (int i = n-1; i >= 0; i--) {
            int idx = k / factorial[i];
            result += to_string(numbers[idx]);
            numbers.erase(numbers.begin() + idx);
            k %= factorial[i];
        }

        return result;
    }
};
```

