import java.util.ArrayList;
import java.util.List;

public class StairWays {
    public static void main(String[] args) {
        int n = 5; // 台阶数
        List<List<Integer>> allWays = new ArrayList<>();
        List<Integer> currentPath = new ArrayList<>();

        findWays(n, currentPath, allWays);

        System.out.println("总共有 " + allWays.size() + " 种走法：");
        for (int i = 0; i < allWays.size(); i++) {
            System.out.println("方法" + (i+1) + ": " + allWays.get(i));
        }
    }

    private static void findWays(int remaining, List<Integer> path, List<List<Integer>> result) {
        if (remaining == 0) {
            result.add(new ArrayList<>(path));
            return;
        }

        if (remaining >= 1) {
            path.add(1);
            findWays(remaining - 1, path, result);
            path.remove(path.size() - 1);
        }

        if (remaining >= 2) {
            path.add(2);
            findWays(remaining - 2, path, result);
            path.remove(path.size() - 1);
        }
    }
}
