```c
#include <stdio.h>

// Hàm Euclide mở rộng
// Tìm d = gcd(a,b) và các hệ số x, y sao cho ax + by = d
void extendedEuclid(int a, int b, int *d, int *x, int *y) {
    // (1) Nếu b = 0
    if (b == 0) {
        *d = a;
        *x = 1;
        *y = 0;
        return;
    }

    // (2) Khởi tạo
    int x2 = 1, x1 = 0;
    int y2 = 0, y1 = 1;

    // (3) While b > 0
    while (b > 0) {
        // 3.1
        int q = a / b;
        int r = a - q * b;
        int x = x2 - q * x1;
        int y = y2 - q * y1;

        // 3.2
        a = b;
        b = r;
        x2 = x1;
        x1 = x;
        y2 = y1;
        y1 = y;
    }

    // (4) Trả về kết quả
    *d = a;
    *x = x2;
    *y = y2;
}

int main() {
    int a, b, d, x, y;

    printf("Nhap a: ");
    scanf("%d", &a);
    printf("Nhap b: ");
    scanf("%d", &b);

    extendedEuclid(a, b, &d, &x, &y);

    printf("gcd(%d, %d) = %d\n", a, b, d);
    printf("Cac he so: x = %d, y = %d\n", x, y);
    printf("Kiem tra: %d*%d + %d*%d = %d\n", a, x, b, y, a*x + b*y);

    return 0;
}
```

